import { Link } from 'react-router-dom';
import "./Ourblogs.css";
import Aos from 'aos';

function Ourblogs() {
    useEffect(() => {
        Aos.init({
            duration: "2000"
        })
    })
    return (
        <Fragment>
            <div className="container text-center" data-aos='fade-up'>
                <h1 className='h1 fs-3 fw-bold' style={{ color: '#bac34e', fontFamily: "Brush Script MT, Brush Script Std, cursive" }}>From Our Blog</h1>
                <h1 className='h1 fw-bold fs-lg-3 fs-sm-6 mt-5' style={{ color: "#0a472e", fontFamily: "roman" }}>Latest Updated</h1>
            </div>
            <div className="container p-4">
                <div className="container">
                    <div className="row">
                        <div className="col-sm-12 col-lg-3">
                            <div className="card" style={{ overflow: 'hidden' }}>
                                <img src={blog1} className="card-img-top" alt="..." style={{ aspectRatio: "1.5" }} />
                                <div className='blogbox1 bg-primary text-center fw-bold text-white fs-5'>Overview</div>
                                <div className="card-body">
                                    <h5 className="card-title">Swabhimaan Card</h5>
                                    <p className="card-text">FDA India introduces <b>SWABHIMAAN CARD</b> to every individual and agricultural business.</p>
                                    <Link to={"/Blogger-page/blog1-data"} className="text-primary text-decoration-none fw-bold bloglink"><p className='text-danger d-inline'> READ MORE</p></Link>
                                </div>
                            </div>
                        </div>
                        <div className="col-sm-12 col-lg-3">
                            <div className="card" style={{ overflow: 'hidden' }}>
                                <img src={blog2} className="card-img-top" alt="..." style={{ aspectRatio: "1.5" }} />
                                <div className='blogbox1 bg-dark text-center fw-bold text-white fs-5'>Inspection</div>
                                <div className="card-body">
                                    <h5 className="card-title">Swabhimaan Kendra</h5>
                                    <p className="card-text">FDA India introduces <b>SWABHIMAAN KENDRA</b> to every People for business.</p>
                                    <Link to={"/"} className="text-dark text-decoration-none fw-bold bloglink"><p className='d-inline text-danger'> READ MORE</p></Link>
                                </div>
                            </div>
                        </div>
                        <div className="col-sm-12 col-lg-3">
                            <div className="card" style={{ overflow: 'hidden' }}>
                                <img src={vill1} className="card-img-top" alt="..." style={{ aspectRatio: "1.5" }} />
                                <div className='blogbox1 bg-success text-center fw-bold text-white fs-5'>Together</div>
                                <div className="card-body">
                                    <h5 className="card-title">Smile Together</h5>
                                    <p className="card-text">text to build on the card title and make up the bulk of the card's content.</p>
                                    <Link href="/" className="text-success text-decoration-none fw-bold bloglink"><p className='d-inline text-danger'> READ MORE</p></Link>
                                </div>
                            </div>
                        </div>
                        <div className="col-sm-12 col-lg-3">
                            <div className="card" style={{ overflow: 'hidden' }} >
                                <img src={vill2} className="card-img-top" alt="..." style={{ aspectRatio: "1.5" }} />
                                <div className='blogbox1 bg-danger text-center fw-bold text-white fs-5'>Quick Learn</div>
                                <div className="card-body">
                                    <h5 className="card-title">Learn Seeding</h5>
                                    <p className="card-text">text to build on the card title and make up the bulk of the card's content.</p>
                                    <Link href="/" className="text-danger text-decoration-none fw-bold bloglink"><p className='d-inline'> READ MORE</p></Link>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <hr />
            </div>
        </Fragment>
    )
}

