import React, { Fragment, useState } from 'react';
import * as XLSX from 'xlsx';

function ExcelReader() {
    const [data, setData] = useState([]);

    const generaterandom = () => {
        const date = new Date();
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const randomNum = Math.floor(Math.random() * 9000000000 + 10000000000);
        return `${year}${month}${day}${randomNum}`;
    }
    const generatetime = () => {
        const date = new Date();
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hour = String(date.getHours()).padStart(2, '0');
        const minute = String(date.getMinutes()).padStart(2, '0');
        const second = String(date.getSeconds()).padStart(2, '0');
        return `${year}-${month}-${day} ${hour}:${minute}:${second}`;
    }
    const handleFileUpload = (event) => {
        const file = event.target.files[0];
        const reader = new FileReader();



        reader.onload = (e) => {
            const binaryStr = e.target.result;
            const workbook = XLSX.read(binaryStr, { type: 'binary' });

            // Access the second sheet by index (index starts at 0)
            const sheetName = workbook.SheetNames[0]; // Sheet 2
            if (sheetName) {
                const worksheet = workbook.Sheets[sheetName];
                const jsonData = XLSX.utils.sheet_to_json(worksheet);

                setData(jsonData);
            } else {
                alert("The Excel file doesn't have a second sheet!");
            }
        };

        reader.readAsBinaryString(file);
    };

    return (
        <div>
            <input type="file" onChange={handleFileUpload} />
            <table className='table'>
                <thead>
                    <tr>
                        {/* Assuming the first row of JSON keys as table headers */}
                        {data.length > 0 && Object.keys(data[0]).map((key) => (
                            <th key={key} scope='col'>{key}</th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {data.map((row, index) => (
                        <tr key={index}>
                            {Object.values(row).map((cell, i) => (
                                <td key={i}>{cell}</td>
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>
            <div className="container">
                <div>
                    INSERT INTO fda_kendra (email, mobile, name, password, state, token, username, total_amount) VALUES
                    {data?.map((d, index) => {
                        return (
                            <Fragment key={index}>
                                <br />
                                ('{d['Email Id']}','{d['Mobile No']}','{d['Name']}','{d.Name?.split(' ')[0]}#1234','bihar',{d.Token},CONCAT('{d.Name?.split(' ')[0]}_',LPAD(FLOOR(RAND()*1000),3,'0')),2370),
                            </Fragment>
                        )
                    })}
                </div>
            </div>
            <h1>Transaction part</h1>
            <div className="container">
                INSERT INTO transaction_kendra (user_id,transaction_id, receipt_number, total_amount, borrow_amount, deposit_amount, discount, local_date, special_allowance, withdraw) VALUES {data.map((d) => {
                    const Randomise = generaterandom();
                    const local_date = generatetime();
                    const total_amount = 2370;
                    const deposit_amount = 2370;
                    return (
                        <Fragment>
                            <br />
                            ('{d.User_id}','{`TRX${Randomise}`}','{`REC${Randomise}`}','{total_amount}','{d.borrow_amount}','{deposit_amount}','{d.discount}','{local_date}','{d.special_allowance}','{d.withdraw}'),
                        </Fragment>
                    )
                })}
            </div>
        </div>
    );
}

export default ExcelReader;
