import React, { Fragment, useEffect } from 'react';
import card2 from "../../crm/assets/images/Swabhimaan-card2.png";
import { FaPiedPiperPp } from "react-icons/fa";
import { FaHandHoldingDollar, FaBowlFood } from "react-icons/fa6";
import arrow1 from "../../crm/assets/images/arraw1.png";
import arrow2 from "../../crm/assets/images/arrow2.png";
import './Home2.css';
import Aos from 'aos';


function Home2() {
    useEffect(() => {
        Aos.init({
            duration: '2000'
        })
    }, [])
    return (
        <Fragment>
            <div className="container-fluid">
                <div className="container">
                    <div className="row g-0">
                        <div className="col-12 text-center" style={{ font: "16px", boxSizing: "border-box" }}>
                            <div className='row'>
                                <div className="col-xxl-6 col-xl-6 col-lg-6 mt-5" data-aos='flip-left' >

                                    <img className="card2" src={card2} alt="" />
                                </div>
                                <div className="col-xxl-6 col-xl-6 col-lg-6 mt-5" data-aos='flip-right' >

                                    <img className="card2" src={card2} alt="" />
                                </div>
                                {/* <img className="card2" src={card2} alt=""  /> */}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div className="m-5 d-lg-none d-xl-none d-xxl-none"></div>
        </Fragment>
    )
}

export default Home2

