import React, { Fragment, useEffect } from 'react';
import './Home.css';
import Aos from 'aos';
import 'aos/dist/aos.css';
import SwabhimaanKendra from '../../crm/assets/images/SWABHIMAAN KENDRA.jpg'
import { Link } from 'react-router-dom';


function Home() {
    useEffect(() => {
        Aos.init({
            duration: 800,
        });
    }, [])
    return (
        <Fragment>
            <div className="container-fluid pb-5 bg-light">
                <div className="container">
                    <div className="row mt-5 g-4">
                        <div className="col-xxl-6 col-xl-6 col-lg-6">
                            <img src={SwabhimaanKendra} className='rounded rounded-4 w-100' alt="" />
                        </div>
                        <div className="col-xxl-6 col-xl-6 col-lg-6">
                            <div className='fs-3 fw-bold mt-3 mb-5 text-center rounded p-2 meetfda' style={{ color: "white", fontFamily: "roman", backgroundColor: "rgba(165,42,42,.9)", boxShadow: "2px 2px 0 0 black", margin: "0 auto" }}>Meet FDA India: Empowering Change</div>
                            <p className='fs-5' style={{ color: "black", textAlign: "justify" }}><b className='text-dark fw-bold'>FDA India</b> was founded in 2022 to deal with the effects of rising inflation due to the COVID-19 pandemic. This inflation affected the economic strength of each individual and the agriculture business.
                            </p>
                            <br />
                            <p className='fs-5' style={{ color: "black", textAlign: "justify" }}>
                                Our goal is to empower individuals by providing the essential resources, funding, knowledge, and technology needed to enhance their lives and boost agricultural productivity. To achieve this, FDA India proudly presents the <b>Swabhimaan Card</b> and <b>Swabhimaan Kendra</b>. These initiatives aim to make sure that everyone has access to funding and products when they need them most.
                            </p>
                            <div className='text-center pt-4'>
                                <Link to={"/crm/user/forkendra"} className='bloglink1 text-decoration-none fw-bolder btn btn-success btn-md'> Apply Now</Link>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Fragment>
    )
}

export default Home
