import React, { Fragment } from 'react'
import image1 from "../../crm/assets/images/slides/card web page.jpg";
import image2 from "../../crm/assets/images/slides/grocery.jpg";
import image3 from "../../crm/assets/images/slides/mission.jpg";
import image4 from "../../crm/assets/images/slides/Organicweb.jpg";
import "./Marquees.css";
import Carousel from 'react-bootstrap/Carousel';
import guide from '../../crm/assets/Files/GUIDELINES_FOR_OPENING_OF_SWABHIMAAN_KENDRA.pdf';
import CardFormHindi from '../../crm/assets/Files/CardFormHindi.pdf';
import CardFormEnglish from '../../crm/assets/Files/CardFormEnglish.pdf';

function Karousal() {
    return (
        <Fragment>
            <div className="container-fluid">
                <div class="marquee-container">
                    <span class="marquee-text fs-5">ONLY BIHAR AND JHARKHAND PEOPLE CAN APPLY FOR NOW.</span>
                </div>
                <div className="row">
                    <div className="col-xxl-2 col-xl-2 d-none d-xxl-block d-xl-block">
                        <h5 className="text-center text-white rounded p-2" style={{ backgroundColor: "#ab183d" }}>
                            Important Notice
                        </h5>
                        <div className="scroll-container">
                            <div className="scroll-content">
                                <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                    Guidelines for Opening Swabhimaan Kendra:-
                                    <span className="blink text-nowrap">
                                        <a href={guide} target='__blank'>click here</a>
                                        <span className="blink1"> new!</span>
                                    </span>
                                </p>
                                <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                    Card Form in Hindi:-
                                    <span className="blink text-nowrap">
                                        <a href={CardFormHindi} target='__blank'>click here</a>
                                        <span className="blink1"> new!</span>
                                    </span>
                                </p>
                                <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                    Card Form in English:-
                                    <span className="blink text-nowrap">
                                        <a href={CardFormEnglish} target='__blank'>click here</a>
                                        <span className="blink1"> new!</span>
                                    </span>
                                </p>
                            </div>
                        </div>
                    </div>



                    <div className="col-xxl-10 col-xl-10 col-sm-12 col-md-12">
                        <Carousel data-bs-theme="light">
                            <Carousel.Item>
                                <img className="d-block w-100" src={image1} alt="First slide" />
                            </Carousel.Item>

                            <Carousel.Item>
                                <img className="d-block w-100" src={image2} alt="Second slide" />
                            </Carousel.Item>
                            <Carousel.Item>
                                <img className="d-block w-100" src={image3} alt="Third slide" />
                            </Carousel.Item>
                            <Carousel.Item>
                                <img className="d-block w-100" src={image4} alt="Forth slide" />
                            </Carousel.Item>
                        </Carousel>
                    </div>
                </div>
            </div>
        </Fragment>
    )
}

export default Karousal

export function ImportantNotice() {
    return (
        <Fragment>
            <div className="container mt-2">
                <div className='col-xxl-2 col-xl-2 d-block d-xxl-none d-xl-none'>
                    <h5 className="text-center text-white rounded p-1 my    -1" style={{ backgroundColor: "#ab183d" }}>
                        Important Notice
                    </h5>
                    <div className="scroll-container1">
                        <div className="scroll-content1">
                            <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                Guidelines for Opening Swabhimaan Kendra:-<span className="blink text-nowrap">
                                    <a href={guide} target='__blank'>click here</a>
                                    <span className="blink1"> new!</span>
                                </span>
                            </p>
                            <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                Card Form in Hindi:-
                                <span className="blink text-nowrap">
                                    <a href={CardFormHindi} target='__blank'>click here</a>
                                    <span className="blink1"> new!</span>
                                </span>
                            </p>
                            <p className="fw-bolder" style={{ fontSize: "13px" }}>
                                Card Form in English:-
                                <span className="blink text-nowrap">
                                    <a href={CardFormEnglish} target='__blank'>click here</a>
                                    <span className="blink1"> new!</span>
                                </span>
                            </p>
                        </div>
                    </div>
                </div>
            </div>

        </Fragment>
    )
}



